577: /// Remove a group from the layout tree, collapsing splits as needed
578: /// Returns true if the group was found and removed
579: fn remove_group_from_layout(layout: &mut LayoutNode, group_id: GroupId) -> bool {
580:     match layout {
581:         LayoutNode::Group(id) => {
582:             // Can't remove at this level - parent needs to handle it
583:             *id == group_id
584:         }
585:         LayoutNode::Split(container) => {
586:             // Find and remove the group from children
587:             let mut found_index = None;
588:             for (i, child) in container.children.iter().enumerate() {
589:                 if let LayoutNode::Group(id) = child {
590:                     if *id == group_id {
591:                         found_index = Some(i);
592:                         break;
593:                     }
594:                 }
595:             }
596: 
597:             if let Some(index) = found_index {
598:                 container.children.remove(index);
599:                 container.ratios.remove(index);
600:                 if !container.min_sizes.is_empty() {
601:                     container
602:                         .min_sizes
603:                         .remove(index.min(container.min_sizes.len() - 1));
604:                 }
605: 
606:                 // Normalize ratios
607:                 let sum: f32 = container.ratios.iter().sum();
608:                 if sum > 0.0 {
609:                     for ratio in &mut container.ratios {
610:                         *ratio /= sum;
611:                     }
612:                 }
613: 
614:                 // If only one child remains, collapse the split
615:                 if container.children.len() == 1 {
616:                     let remaining = container.children.remove(0);
617:                     *layout = remaining;
618:                 }
619: 
620:                 return true;
621:             }
622: 
623:             // Recursively search children
624:             for child in &mut container.children {
625:                 if remove_group_from_layout(child, group_id) {
626:                     // Check if we need to collapse after recursive removal
627:                     if let LayoutNode::Split(inner) = child {
628:                         if inner.children.len() == 1 {
629:                             let remaining = inner.children.remove(0);
630:                             *child = remaining;
631:                         }
632:                     }
633:                     return true;
634:                 }
635:             }
636: 
637:             false
638:         }
639:     }
640: }
