281:     /// Compute layout for all groups given the available rectangle.
282:     /// Updates the `rect` field of each EditorGroup.
283:     /// Returns a list of splitter bar positions for rendering/hit testing.
284:     pub fn compute_layout(&mut self, available: Rect) -> Vec<SplitterBar> {
285:         let mut splitters = Vec::new();
