289: 
290:     /// Recursively compute layout for a node
291:     fn compute_layout_node(
292:         &mut self,
293:         node: &LayoutNode,
294:         rect: Rect,
295:         splitters: &mut Vec<SplitterBar>,
296:     ) {
297:         match node {
298:             LayoutNode::Group(group_id) => {
299:                 if let Some(group) = self.groups.get_mut(group_id) {
300:                     group.rect = rect;
301:                 }
302:             }
303:             LayoutNode::Split(container) => {
304:                 let children = &container.children;
305:                 let ratios = &container.ratios;
306: 
307:                 if children.is_empty() {
308:                     return;
309:                 }
310: 
311:                 // Calculate child rects based on direction and ratios
312:                 let mut offset = 0.0;
313:                 let total_size = match container.direction {
314:                     SplitDirection::Horizontal => rect.width,
315:                     SplitDirection::Vertical => rect.height,
316:                 };
317: 
318:                 for (i, child) in children.iter().enumerate() {
319:                     let ratio = ratios
320:                         .get(i)
321:                         .copied()
322:                         .unwrap_or(1.0 / children.len() as f32);
323:                     let child_size = total_size * ratio;
324: 
325:                     let child_rect = match container.direction {
326:                         SplitDirection::Horizontal => {
327:                             Rect::new(rect.x + offset, rect.y, child_size, rect.height)
328:                         }
329:                         SplitDirection::Vertical => {
330:                             Rect::new(rect.x, rect.y + offset, rect.width, child_size)
331:                         }
332:                     };
333: 
334:                     // Add splitter bar between children (not after last child)
335:                     if i < children.len() - 1 {
336:                         let splitter = match container.direction {
337:                             SplitDirection::Horizontal => SplitterBar {
338:                                 direction: container.direction,
339:                                 rect: Rect::new(
340:                                     rect.x + offset + child_size - SPLITTER_WIDTH / 2.0,
341:                                     rect.y,
342:                                     SPLITTER_WIDTH,
343:                                     rect.height,
344:                                 ),
345:                                 index: i,
346:                             },
347:                             SplitDirection::Vertical => SplitterBar {
348:                                 direction: container.direction,
349:                                 rect: Rect::new(
350:                                     rect.x,
351:                                     rect.y + offset + child_size - SPLITTER_WIDTH / 2.0,
352:                                     rect.width,
353:                                     SPLITTER_WIDTH,
354:                                 ),
355:                                 index: i,
356:                             },
357:                         };
358:                         splitters.push(splitter);
359:                     }
360: 
361:                     // Recursively layout child
362:                     self.compute_layout_node(child, child_rect, splitters);
363: 
364:                     offset += child_size;
365:                 }
366:             }
367:         }
368:     }
