397:     /// Find splitter bar at a given point (for drag handling)
398:     pub fn splitter_at_point(&self, splitters: &[SplitterBar], x: f32, y: f32) -> Option<usize> {
399:         for (i, splitter) in splitters.iter().enumerate() {
400:             if splitter.rect.contains(x, y) {
401:                 return Some(i);
402:             }
403:         }
404:         None
405:     }
406: }
