107: /// Blend a source pixel (with alpha) onto a destination pixel
108: ///
109: /// Both colors are in ARGB format. The source alpha determines
110: /// the blend ratio.
111: #[inline]
112: pub fn blend_pixel(src: u32, dst: u32) -> u32 {
113:     let alpha = ((src >> 24) & 0xFF) as u32;
114:     if alpha == 0 {
115:         return dst;
116:     }
117:     if alpha == 255 {
118:         return src | 0xFF000000;
119:     }
120: 
121:     let inv_alpha = 255 - alpha;
122: 
123:     let r = ((((src >> 16) & 0xFF) * alpha + ((dst >> 16) & 0xFF) * inv_alpha) / 255) & 0xFF;
124:     let g = ((((src >> 8) & 0xFF) * alpha + ((dst >> 8) & 0xFF) * inv_alpha) / 255) & 0xFF;
125:     let b = (((src & 0xFF) * alpha + (dst & 0xFF) * inv_alpha) / 255) & 0xFF;
126: 
127:     0xFF000000 | (r << 16) | (g << 8) | b
128: }
129: 
130: /// Render an overlay background with alpha blending
131: ///
132: /// # Arguments
133: /// * `buffer` - The framebuffer to render into
134: /// * `bounds` - The overlay bounds
135: /// * `background` - Background color in ARGB format
136: /// * `buffer_width` - Width of the framebuffer in pixels
137: /// * `buffer_height` - Height of the framebuffer in pixels
138: pub fn render_overlay_background(
139:     buffer: &mut [u32],
140:     bounds: &OverlayBounds,
141:     background: u32,
142:     buffer_width: usize,
143:     buffer_height: usize,
144: ) {
145:     let y_end = bounds.bottom().min(buffer_height);
146:     let x_end = bounds.right().min(buffer_width);
147: 
148:     for py in bounds.y..y_end {
149:         for px in bounds.x..x_end {
150:             let idx = py * buffer_width + px;
151:             if idx < buffer.len() {
152:                 buffer[idx] = blend_pixel(background, buffer[idx]);
153:             }
154:         }
155:     }
156: }
