158: /// Render a 1px border around overlay bounds
159: ///
160: /// # Arguments
161: /// * `buffer` - The framebuffer to render into
162: /// * `bounds` - The overlay bounds
163: /// * `border_color` - Border color in ARGB format
164: /// * `buffer_width` - Width of the framebuffer in pixels
165: /// * `buffer_height` - Height of the framebuffer in pixels
166: pub fn render_overlay_border(
167:     buffer: &mut [u32],
168:     bounds: &OverlayBounds,
169:     border_color: u32,
170:     buffer_width: usize,
171:     buffer_height: usize,
172: ) {
173:     let y_end = bounds.bottom().min(buffer_height);
174:     let x_end = bounds.right().min(buffer_width);
175: 
176:     // Top edge
177:     if bounds.y < buffer_height {
178:         for px in bounds.x..x_end {
179:             let idx = bounds.y * buffer_width + px;
180:             if idx < buffer.len() {
181:                 buffer[idx] = border_color | 0xFF000000;
182:             }
183:         }
184:     }
185: 
186:     // Bottom edge
187:     let bottom_y = y_end.saturating_sub(1);
188:     if bottom_y > bounds.y && bottom_y < buffer_height {
189:         for px in bounds.x..x_end {
190:             let idx = bottom_y * buffer_width + px;
191:             if idx < buffer.len() {
192:                 buffer[idx] = border_color | 0xFF000000;
193:             }
194:         }
195:     }
196: 
197:     // Left edge
198:     if bounds.x < buffer_width {
199:         for py in bounds.y..y_end {
200:             let idx = py * buffer_width + bounds.x;
201:             if idx < buffer.len() {
202:                 buffer[idx] = border_color | 0xFF000000;
203:             }
204:         }
205:     }
206: 
207:     // Right edge
208:     let right_x = x_end.saturating_sub(1);
209:     if right_x > bounds.x && right_x < buffer_width {
210:         for py in bounds.y..y_end {
211:             let idx = py * buffer_width + right_x;
212:             if idx < buffer.len() {
213:                 buffer[idx] = border_color | 0xFF000000;
214:             }
215:         }
216:     }
217: }
